#include <stdio.h>

void double_all(int a[], int n) {
    for (int i = 0; i < n; i++) {
        a[i] *= 2;
    }
}

int main() {
    int values[] = {1, 2, 3, 4};
    double_all(values, 4);
    for (int i = 0; i < 4; i++) {
        printf("%d ", values[i]);
    }
    printf("\n");
    return 0;
}
